// Parse: !card <title> | <description>
const raw = ($json.body?.content ?? $json.content ?? '').trim();
const text = raw.replace(/^!card\s*/i, '');
const [titlePart, ...descParts] = text.split('|');
const title = (titlePart || '').trim();
const description = descParts.join('|').trim();
const author = $json.body?.author?.username ?? $json.author?.username ?? 'unknown';
return { json: { title, description, author, raw } };
